UPDATE document_definition_versions
SET schema_json = '{"code":"CANADA_PERMANENT_RESIDENT","country":"CA","documentType":"RESIDENCE_PERMIT","version":"2015","side":"BACK","mrzFormat":"TD1","reading":"Canada permanent resident card back. The mrz value is three lines of exactly 30 characters, separated by newlines. Second line positions, counted from 1: 1-6 birth date, 7 its check digit, 8 the sex letter, 9-14 the expiry as YYMMDD, 15 its check digit, 16-18 nationality, then an optional date after a <. expirationDate uses only positions 9-14. Positions 9-10 are the year, 11-12 the month, 13-14 the day. A year 30 is 2030. The day is positions 13-14. Do not take the day from the later optional date. Third line: letters and < only, no digits. A round character is the letter O, never the digit 0, and it stays in the surname. Do not drop it when writing lastName. The line ends with < fillers. After writing it, count the characters. If the count is 29, add one final < so the count is 30. The < character belongs only in the mrz field. lastName and firstName use spaces: one < between surnames is a space, and << ends the surnames.","fields":[{"name":"documentNumber","type":"DOCUMENT_NUMBER","required":true,"hint":"the PD number printed above the machine-readable zone; do not use the front ID No"},{"name":"lastName","type":"NAME","required":false,"normalizer":"ICAO_NAME","hint":"every surname letter before <<, including a leading O. Write spaces, no <, and do not drop a letter that looked like 0"},{"name":"firstName","type":"NAME","required":false,"normalizer":"ICAO_NAME","hint":"given names after <<, written with spaces and with no < character"},{"name":"dateOfBirth","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"birth date from the MRZ; write yyyy-MM-dd"},{"name":"expirationDate","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"second MRZ line positions 9-14, counted from 1: year, month, day. Write yyyy-MM-dd. A year 30 is 2030. The day is positions 13-14, not the optional date later on the line"},{"name":"sex","type":"SEX","required":false,"hint":"sex letter from the MRZ"},{"name":"nationality","type":"NATIONALITY","required":false,"hint":"nationality alpha-3 from the MRZ, such as CMR"},{"name":"mrz","type":"MRZ","required":true,"hint":"three lines of 30 characters. The third line has letters and < only: write O, not 0. If that line counts 29, add one final <"},{"name":"placeOfLanding","type":"STRING","required":false,"hint":"labeled Place of landing"},{"name":"residentSince","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"labeled PR Since; write yyyy-MM-dd"},{"name":"eyeColor","type":"STRING","required":false,"hint":"labeled Eyes"},{"name":"heightCm","type":"STRING","required":false,"hint":"labeled Height, digits only"},{"name":"countryOfBirth","type":"NATIONALITY","required":false,"hint":"labeled COB, alpha-3 such as CMR"}],"rules":[]}'
WHERE id = '018f5a00-0000-7000-8000-0000000000e4';
